import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {join,dirname,resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {instrumentTypeScriptWithCoverage} from '../scripts/run-istanbul-bun-coverage';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
import {sourceHash} from '../scripts/quality-inventory';
const root=process.cwd(),storage=createOwnedTestDirectory('memory-graph-persona-diagnostic-');
const repositories=["src/infrastructure/database/repositories/graph-repository.ts","src/infrastructure/database/repositories/persona-repository.ts"];
const driver="tests/infrastructure/database/repositories/graph-persona-lifecycle.test.ts",paths=[...repositories,driver];
const tests=["tests/infrastructure/database/repositories/graph-persona-lifecycle.test.ts","tests/infrastructure/database/repositories/graph-repository.test.ts","tests/infrastructure/database/repositories/persona-repository.test.ts"];
const mode=process.argv[2]??'measure';if(!['measure','faults'].includes(mode))throw Error('Invalid mode');
const originals=new Map(paths.map(path=>[path,readFileSync(path,'utf8')]));
function put(path:string,content:string){mkdirSync(dirname(join(storage.dir,path)),{recursive:true});writeFileSync(join(storage.dir,path),content);}
const runs:any[]=[];
try{
 for(const path of tests.slice(1))put(path,readFileSync(path,'utf8'));
 for(const path of ['src/infrastructure/database/connection.ts','src/infrastructure/database/owned-database.ts','src/infrastructure/database/schema.ts','src/domain/entities/graph-edge.ts','src/domain/entities/persona-entry.ts'])put(path,'export * from '+JSON.stringify(join(root,path).replaceAll('\\','/'))+';');
 put('capture.ts','import {afterAll} from "bun:test";import {writeFileSync} from "node:fs";afterAll(()=>writeFileSync("coverage.json",JSON.stringify((globalThis as any).__coverage__)));');
 put('bunfig.toml','[test]\ncoverage=false\npreload=['+JSON.stringify(join(root,'tests/test-setup.ts').replaceAll('\\','/'))+(mode==='measure'?',"./capture.ts"':'')+']\n');
 const faults=mode==='faults'?[
  ...repositories.flatMap(path=>[...originals.get(path)!.matchAll(/using \w+ =/g)].map((match,index)=>({path,index,offset:match.index,kind:'missing-disposal'}))),
  ...repositories.flatMap(path=>[{path,index:0,offset:0,kind:'missing-transaction'},{path,index:0,offset:0,kind:'false-save-success'},{path,index:0,offset:0,kind:'false-batch-success'}]),
 ]:[];
 for(const fault of [null,...faults]){
  for(const [path,content]of originals)put(path,mode==='measure'?instrumentTypeScriptWithCoverage(content,resolve(path)).code:content);
  if(fault){const content=originals.get(fault.path)!;put(fault.path,fault.kind==='missing-disposal'?content.slice(0,fault.offset)+'const'+content.slice(fault.offset+5):fault.kind==='missing-transaction'?content.replace('this.db.transaction(', '('):fault.kind==='false-save-success'?content.replace(/if \(!saved\) throw new Error\([^;]+;/, 'if (!saved) return null as any;'):content.replace(/if \(!current\) throw new Error\([^;]+;/, 'if (!current) continue;'));}
  const command=[process.execPath,'test','--timeout','15000',...(mode==='measure'?tests:[driver])];
  const child=Bun.spawnSync(command,{cwd:storage.dir,env:{...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe',timeout:45000});
  const output=new TextDecoder().decode(child.stdout)+new TextDecoder().decode(child.stderr);
  runs.push({fault,command,exit:child.exitCode,output});
  if(fault?child.exitCode===0||!output.includes('(fail)'):child.exitCode!==0)throw Error('Unexpected result\n'+output);
 }
 let measurement:unknown;
 if(mode==='measure'){
  const raw=JSON.parse(readFileSync(join(storage.dir,'coverage.json'),'utf8')),map=createCoverageMap(raw);
  const files=paths.map(path=>{const measured=map.fileCoverageFor(resolve(path)),data=measured.data;return{path,sourceHash:sourceHash(originals.get(path)!),metrics:measured.toSummary().data,uncoveredBranches:Object.entries(data.b).flatMap(([id,hits])=>hits.flatMap((count,index)=>count===0?[{id,index,location:data.branchMap[id]?.locations[index]}]:[])),uncoveredFunctions:Object.entries(data.f).filter(([,hits])=>hits===0).map(([id])=>data.fnMap[id])};});
  measurement={files,rawCoverage:raw};console.log(JSON.stringify(files));
 }else console.log(JSON.stringify(runs.map(run=>({fault:run.fault,exit:run.exit}))));
 writeFileSync(`.git/b11-graph-persona-${mode}.json`,JSON.stringify({recordedAt:new Date().toISOString(),scope:'Scoped diagnostic; full instrumenter/platform/package/changed-line and independent review acceptance remains open.',runtime:Bun.version,sourceInputs:paths.map(path=>({path,sourceHash:sourceHash(originals.get(path)!)})),runs,measurement,source:readFileSync('.git/b11-graph-persona-diagnostic.ts','utf8')},null,2)+'\n');
}finally{storage.cleanup();}

