import {strict as assert} from 'node:assert';
import {readFileSync,writeFileSync,existsSync} from 'node:fs';
import {resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {discoverInventory,validateInventory,sourceHash} from '../scripts/quality-inventory';
const base='.planning/memory-resilience/',read=(p:string)=>JSON.parse(readFileSync(p,'utf8'));
const path=base+'evidence/B11.74.3-graph-persona.json',record=read(path),catalog=discoverInventory(process.cwd());
assert.equal(catalog.files.length,455);assert.equal(catalog.packages.length,2);assert.deepEqual(catalog,read(base+'executable-catalog.json'));assert.deepEqual(validateInventory(catalog,read(base+'quality-classifications.json')),[]);
for(const input of [...record.sourceInputs,...record.otherInputs])assert.equal(input.sourceHash,sourceHash(readFileSync(input.path,'utf8')));
for(const input of record.sourceInputs)for(const rows of [record.diagnosticCoverage.sourceInputs,record.decisionChecks.sourceInputs,record.native.sourceInputs])assert.equal(rows.find((r:any)=>r.path===input.path).sourceHash,input.sourceHash);
const coverage=createCoverageMap(record.diagnosticCoverage.measurement.rawCoverage);
for(const entry of record.diagnosticCoverage.measurement.files){assert.deepEqual(coverage.fileCoverageFor(resolve(entry.path)).toSummary().data,entry.metrics);for(const metric of Object.values(entry.metrics)as any[])assert.equal(metric.pct,100);}
for(const run of [record.checks[0],...record.native.runs]){assert.equal(run.exit,0);assert(run.output.includes('17 pass')&&run.output.includes('0 fail')&&run.output.includes('855 expect()'));}
assert.equal(record.decisionChecks.runs.length,21);assert.equal(record.decisionChecks.runs[0].exit,0);for(const run of record.decisionChecks.runs.slice(1)){assert.equal(run.exit,1);assert(run.output.includes('(fail)'));}
assert(!existsSync(record.removedRuntimeRoot));
const ledger=read(base+'work-items.json'),items=new Map<string,any>(ledger.items.map((i:any)=>[i.id,i])),done=new Set<string>();
function visit(id:string,stack=new Set<string>()){assert(items.has(id)&&!stack.has(id),'Invalid dependency '+id);if(done.has(id))return;for(const dep of items.get(id).depends_on)visit(dep,new Set([...stack,id]));done.add(id);}
assert.equal(items.size,232);assert.equal(items.size,ledger.items.length);for(const id of items.keys())visit(id);
assert.equal(ledger.current_item,'B11.74.3');assert.deepEqual(ledger.items.filter((i:any)=>i.status==='active').map((i:any)=>i.id),['B11.74.3']);
const inventory=items.get('B11.74.3').progress.repositoryInventory;assert.equal(inventory.length,17);assert.equal(inventory.filter((r:any)=>r.status.startsWith('local')).length,11);assert.equal(inventory.filter((r:any)=>r.status.startsWith('local')).reduce((n:number,r:any)=>n+r.nativePrepareSites,0),90);
for(const entry of inventory)assert.equal(entry.sourceHash,sourceHash(readFileSync(entry.path,'utf8')));
for(const input of record.sourceInputs.slice(0,2)){const source=readFileSync(input.path,'utf8');assert.equal([...source.matchAll(/this\.db\.prepare[<(]/g)].length,7);assert.equal([...source.matchAll(/using \w+ =/g)].length,7);assert(!source.includes('this.db.query('));}
assert.equal(record.caller.exit,0);assert(record.caller.output.includes('2 pass')&&record.caller.output.includes('13 expect()'));assert(!existsSync(record.caller.storageRoot));for(const input of record.caller.sourceInputs)assert.equal(input.sourceHash,sourceHash(readFileSync(input.path,'utf8')));
for(const id of ['Q024','Q029']){assert.equal(items.get(id).status,'pending');assert.deepEqual(items.get(id).depends_on,['B11.74.3']);assert(items.get('B11.74.7').depends_on.includes(id));}
assert.equal(items.get('B11.74').status,'pending');assert.equal(items.get('B11.74.6').status,'pending');assert(!readFileSync('src/infrastructure/database/connection.ts','utf8').includes('OwnedDatabase'));
record.validation={command:'bun .git/b11-graph-persona-validate.ts',exit:0,recordedAt:new Date().toISOString(),result:'455-file/two-package inventory and 232-item acyclic ledger reconcile. Eleven repositories/90 prepares locally migrated; graph/persona batch result integrity repaired. Final source/native/metric/fault evidence agrees; full acceptance and factory activation pending.',source:readFileSync('.git/b11-graph-persona-validate.ts','utf8')};
writeFileSync(path,JSON.stringify(record,null,2)+'\n');console.log(record.validation.result);
